    const raw=JSON.stringify(manager.recipient),current=await ghApi('/gists/'+gid);check();
    if(current.public!==false||current.owner?.id!==_managerCapability.ownerId||current.owner?.login!==_managerCapability.ownerLogin)throw Error();
    const old=current.files?.[RATIO_RECIPIENT_FILE],revision=current.history?.[0]?.version;
