  }catch{if(ticket===_ratioRecipientPreviewTicket){clearRatioRecipientPreview();document.getElementById('ratioRecipientStatus').textContent='预览未通过：请核验管理人、来源及是否已有不同公钥；没有写入。';}return false;}
}
async function registerRatioRecipient(event){
  const preview=_ratioRecipientPreview;
  if(event?.isTrusted!==true||!preview||document.getElementById('ratioRecipientConsent').checked!==true)return false;
  _ratioRecipientPreview=null;document.getElementById('ratioRecipientConfirm').disabled=true;
  const check=()=>{if(document.getElementById('ratioRecipientConsent').checked!==true||document.getElementById('ratioRecipientFingerprint').textContent!==preview.fingerprint||document.getElementById('ratioRecipientScope').textContent!==preview.scopeId||preview.ticket!==_ratioRecipientPreviewTicket||!ratioAuthorized()||preview.epoch!==_sourceEpoch||preview.who!==ratioIdentity()||Date.now()<preview.createdAt||Date.now()-preview.createdAt>300000||EDIT.draft||EDIT.pending||_ledgerBusy)throw Error();};
  try{
    check();if(_ratioRecipientWrite||_ratioSnapshotWrite||!await verifyRatioCapabilityNow())throw Error();check();
    const {gid,raw}=preview,current=await ghApi('/gists/'+gid);check();
    if(current.public!==false||current.owner?.id!==_managerCapability.ownerId||current.owner?.login!==_managerCapability.ownerLogin||current.history?.[0]?.version!==preview.revision)throw Error();
    const old=current.files?.[RATIO_RECIPIENT_FILE];if(old&&(old.truncated||old.content!==raw))throw Error();
    if(!old){const op={gid,token:cfg(K.tok),epoch:_sourceEpoch,raw};_ratioRecipientWrite=op;
      try{check();await ghApi('/gists/'+gid,{method:'PATCH',body:JSON.stringify({files:{[RATIO_RECIPIENT_FILE]:{content:raw}}}),reviewedRatioRecipient:op});}finally{if(_ratioRecipientWrite===op)_ratioRecipientWrite=null;}
    }
