    if(back.public!==false||back.owner?.id!==_managerCapability.ownerId||back.owner?.login!==_managerCapability.ownerLogin||back.files?.[RATIO_RECIPIENT_FILE]?.truncated||back.files?.[RATIO_RECIPIENT_FILE]?.content!==raw)throw Error();
    clearRatioRecipientPreview();saveBlob('ratio-manager-public-recipient.json',raw+'\n','application/json');document.getElementById('ratioRecipientStatus').textContent='已登记并回读此公钥；下载文件仅含公开配置，未导出凭据。';return true;
  }catch{clearRatioRecipientPreview();document.getElementById('ratioRecipientStatus').textContent='登记未完成或结果未确认；请重新预览检查配置，不会自动重试。';return false;}
}
async function importRatioCipher(file){
  if(!ratioAuthorized()||!file||file.size<1||file.size>3*1024*1024)return;
  const who=ratioIdentity();clearRatioManagement();const ticket=_ratioTicket;
  try{const raw=await file.text();if(ticket!==_ratioTicket||who!==ratioIdentity()||!ratioAuthorized())return;
    const envelope=JSON.parse(raw);if(envelope?.schema!==ratioCore.ENVELOPE)throw Error();_ratioPreview=envelope;_ratioLastEnvelope=null;await renderRatioManagement();
  }catch{clearRatioManagement();toast("仅接受管理人专用密文；原数据未改变");}
}
const ratioSnapshotParse=s=>createLegacyPolicy().parseExactJson(typeof s==='string'?new TextEncoder().encode(s):s);
const RATIO_SNAPSHOT_FILE='fee-console-ratio-snapshot.json';
const ratioSnapshotCore=createRatioSnapshotCore(ratioCore,ratioExposureCore,createRatioSourceCore,ratioSnapshotParse);
let _ratioSnapshotReview=null,_ratioSnapshotFiles={},_ratioSnapshotWrite=null,_ratioSnapshotUnknown=null,_ratioSnapshotGeneration=0;
function clearRatioSnapshotReview(forgetFiles=false){
  ++_ratioSnapshotGeneration;_ratioSnapshotReview=null;
  const panel=document.getElementById('ratioSnapshotReview');if(panel)panel.hidden=true;
  const consent=document.getElementById('ratioSnapshotConsent');if(consent)consent.checked=false;
  const confirm=document.getElementById('ratioSnapshotConfirm');if(confirm)confirm.disabled=true;
  if(forgetFiles){_ratioSnapshotFiles={};for(const id of ['ratioSnapshotCandidate','ratioSnapshotOriginal','ratioSnapshotInput']){const e=document.getElementById(id);if(e)e.value='';}}
}
function ratioSnapshotGist(gist){
  if(!ratioAuthorized()||gist?.public!==false||gist.owner?.id!==_managerCapability.ownerId||gist.owner?.login!==_managerCapability.ownerLogin||!/^[a-f0-9]{40,64}$/.test(gist.history?.[0]?.version||''))throw Error('RATIO_SNAPSHOT_REFUSED');
  return gist;
}
function ratioSnapshotFile(gist,name){const f=gist.files?.[name];if(!f)return null;if(f.truncated||typeof f.content!=='string'||new TextEncoder().encode(f.content).length>5*1024*1024)throw Error('RATIO_SNAPSHOT_REFUSED');return f.content;}
async function renderIndependentRatio(){
  if(!ratioAuthorized()||!document.getElementById('p-ratio').classList.contains('on'))return false;
  const who=ratioIdentity(),ticket=++_ratioTicket,notice=document.getElementById('ratioNotice');
  const check=()=>{if(ticket!==_ratioTicket||who!==ratioIdentity()||!ratioAuthorized()||!document.getElementById('p-ratio').classList.contains('on'))throw Error('RATIO_SNAPSHOT_REFUSED');};
  let found=false;
  try{
    if(!await verifyRatioCapabilityNow())throw Error();check();
    const gist=ratioSnapshotGist(await ghApi('/gists/'+cfg(K.gid)));check();
    const raw=ratioSnapshotFile(gist,RATIO_SNAPSHOT_FILE);if(raw===null)return false;found=true;
    const packet=ratioSnapshotParse(raw),manager=await ratioCore.deriveSnapshotManager(cfg(K.gid),cfg(K.key),cfg(K.tok));check();
    const recipient=ratioSnapshotFile(gist,RATIO_RECIPIENT_FILE);if(recipient===null||ratioCore.canonical(ratioSnapshotParse(recipient))!==ratioCore.canonical(manager.recipient))throw Error();
    const key='feeConsole.ratioSnapshotWatermark.'+manager.recipient.recipientId;let watermark=null;
    try{watermark=cfg(key)?JSON.parse(cfg(key)):null;}catch{throw Error();}
    const result=await ratioSnapshotCore.verify(packet,manager,{watermark});check();if(!store)throw Error();
    store.setItem(key,JSON.stringify(result.watermark));document.getElementById('ratioContent').innerHTML=ratioCore.render(result.model);
