    clearTimeout(_ratioExpiry);_ratioExpiry=setTimeout(()=>{clearRatioManagement();notice.textContent='管理人查看已锁定，请重新打开比例管理核验。';},RATIO_SESSION_MS);return true;
  }catch{if(ticket===_ratioTicket){document.getElementById('ratioContent').replaceChildren();notice.textContent='独立比例文件或管理人核验失败，未显示旧内容。';}return true;}
}
async function previewRatioSnapshot(event){
  if(event?.isTrusted!==true||!ratioAuthorized()||EDIT.draft||EDIT.pending||_ledgerBusy||_ratioRecipientWrite||_ratioSnapshotWrite||_ratioSnapshotUnknown)return false;
  clearRatioSnapshotReview();const ticket=_ratioSnapshotGeneration,who=ratioIdentity(),gid=cfg(K.gid),createdAt=Date.now();
  const check=()=>{if(ticket!==_ratioSnapshotGeneration||who!==ratioIdentity()||!ratioAuthorized()||EDIT.draft||EDIT.pending||_ledgerBusy||_ratioSnapshotUnknown)throw Error();};
  try{
    const files=['candidate','original','input'].map(k=>_ratioSnapshotFiles[k]);if(files.some(f=>!f||f.size<1||f.size>5*1024*1024))throw Error();
    if(!await verifyRatioCapabilityNow())throw Error();check();
    const [candidateText,originalBuffer,inputBuffer]=await Promise.all([files[0].text(),files[1].arrayBuffer(),files[2].arrayBuffer()]);check();
    const packet=ratioSnapshotParse(candidateText);if(packet.authentication!==null)throw Error();
    await ratioSnapshotCore.bodyCheck(packet.body);
    // Read-only review uses the existing decrypt purpose. Authentication is a
    // separate purpose invoked only after the second, explicit trusted consent.
    const manager=await ratioCore.deriveManager(gid,cfg(K.key),cfg(K.tok));check();
    const gist=ratioSnapshotGist(await ghApi('/gists/'+gid));check();
    const registered=ratioSnapshotFile(gist,RATIO_RECIPIENT_FILE);if(registered===null||ratioCore.canonical(ratioSnapshotParse(registered))!==ratioCore.canonical(manager.recipient))throw Error();
    const model=await ratioCore.open(packet.body.envelope,manager),s=packet.body.source;
    const proof=await ratioSnapshotCore.verifyOriginal({originalBytes:new Uint8Array(originalBuffer),inputBytes:new Uint8Array(inputBuffer),model,recipient:manager.recipient,sourceSha256:s.sourceSha256,inputSha256:s.inputSha256,libraryVersion:s.libraryVersion});check();
    if(ratioCore.canonical(proof.evidence)!==ratioCore.canonical(s))throw Error();
    const priorRaw=ratioSnapshotFile(gist,RATIO_SNAPSHOT_FILE),prior=priorRaw===null?null:ratioSnapshotParse(priorRaw);
    if(prior?packet.body.version!==prior.body.version+1||packet.body.previousSnapshotId!==await ratioCore.digest(prior.body):packet.body.version!==1||packet.body.previousSnapshotId!==null)throw Error();
    const profileSha256=await ratioCore.digest([createOfficialRatioSourceCore.toString(),createFeeCompanyExposureCore.toString(),createRatioSnapshotCore.toString(),createRatioSourceCore.toString(),createFeeRatioCore.toString(),createRankedExposureCore.toString()]);check();
    const summary='仅写入同一私密 Gist 的 '+RATIO_SNAPSHOT_FILE+'；版本 '+packet.body.version+'；来源截至 '+s.asOf+'；原采集 '+s.capturedAt+'；原证据到期 '+s.expiresAt+'；接收指纹 '+manager.recipient.recipientId+'；scope '+manager.recipient.scopeId+'；原件 SHA256 '+s.sourceSha256+'；模型 SHA256 '+s.modelSha256+'。使用现有管理人凭据派生仅在内存的认证子密钥，不修改管理费 data/health 或原账本；五分钟有效。';
    _ratioSnapshotReview={ticket,who,gid,createdAt,packet,proof,prior,priorRaw,revision:gist.history[0].version,profileSha256,summary};
    document.getElementById('ratioSnapshotSummary').textContent=summary;document.getElementById('ratioSnapshotReview').hidden=false;document.getElementById('ratioSnapshotConfirm').disabled=false;
    clearTimeout(_ratioExpiry);_ratioExpiry=setTimeout(()=>clearRatioManagement(),RATIO_SESSION_MS);
    document.getElementById('ratioContent').innerHTML=ratioCore.render(model);
    if(typeof styleRatioReport==='function')styleRatioReport(document.getElementById('ratioContent'));
    document.getElementById('ratioNotice').textContent='本机独立比例候选预览，尚未投递。原件完整关联复核通过。';return true;
  }catch{if(ticket===_ratioSnapshotGeneration){clearRatioSnapshotReview();document.getElementById('ratioSnapshotStatus').textContent='预览未通过；检查原件、转换文件、版本及原证据时效。没有写入。';}return false;}
}
async function confirmRatioSnapshot(event){
  const p=_ratioSnapshotReview;if(event?.isTrusted!==true||!p||document.getElementById('ratioSnapshotConsent').checked!==true)return false;
  const check=()=>{if(p.ticket!==_ratioSnapshotGeneration||p.who!==ratioIdentity()||!ratioAuthorized()||Date.now()<p.createdAt||Date.now()-p.createdAt>300000||document.getElementById('ratioSnapshotConsent').checked!==true||document.getElementById('ratioSnapshotSummary').textContent!==p.summary||EDIT.draft||EDIT.pending||_ledgerBusy)throw Error();};
  _ratioSnapshotReview=null;document.getElementById('ratioSnapshotConfirm').disabled=true;let dispatched=false;
  try{
    check();if(_ratioSnapshotWrite||_ratioRecipientWrite||_ratioSnapshotUnknown||!await verifyRatioCapabilityNow())throw Error();check();
    const gist=ratioSnapshotGist(await ghApi('/gists/'+p.gid));check();
    if(gist.history[0].version!==p.revision||ratioSnapshotFile(gist,RATIO_SNAPSHOT_FILE)!==p.priorRaw)throw Error();
    const manager=await ratioCore.deriveSnapshotManager(p.gid,cfg(K.key),cfg(K.tok));check();
    const registered=ratioSnapshotFile(gist,RATIO_RECIPIENT_FILE);if(registered===null||ratioCore.canonical(ratioSnapshotParse(registered))!==ratioCore.canonical(manager.recipient))throw Error();
    const authenticated=await ratioSnapshotCore.authenticate(p.packet,p.proof,manager,{previous:p.prior,profileSha256:p.profileSha256});check();
    const raw=JSON.stringify(authenticated),op={gid:p.gid,token:cfg(K.tok),epoch:_sourceEpoch,raw};_ratioSnapshotWrite=op;_ratioSnapshotUnknown={gid:p.gid,who:p.who,raw};
    try{check();dispatched=true;await ghApi('/gists/'+p.gid,{method:'PATCH',body:JSON.stringify({files:{[RATIO_SNAPSHOT_FILE]:{content:raw}}}),reviewedRatioSnapshot:op});}finally{if(_ratioSnapshotWrite===op)_ratioSnapshotWrite=null;}
    check();const back=ratioSnapshotGist(await ghApi('/gists/'+p.gid));check();if(ratioSnapshotFile(back,RATIO_SNAPSHOT_FILE)!==raw)throw Error();await ratioSnapshotCore.verify(authenticated,manager);check();
    _ratioSnapshotUnknown=null;clearRatioSnapshotReview(true);_ratioPreview=null;document.getElementById('ratioSnapshotStatus').textContent='独立加密比例文件已投递并精确回读；原账本和管理费 data/health 未修改。';await renderRatioManagement();return true;
  }catch{if(!dispatched)_ratioSnapshotUnknown=null;document.getElementById('ratioSnapshotStatus').textContent=dispatched?'投递结果待核对，禁止重复投递；仅可点击只读核对结果。':'投递未执行；没有改变原账本。';return false;}
}
async function exportCurrentRatioSnapshot(event){
  if(event?.isTrusted!==true||!ratioAuthorized()||EDIT.draft||EDIT.pending||_ledgerBusy||_ratioSnapshotWrite||_ratioRecipientWrite||_ratioSnapshotUnknown)return false;
  const who=ratioIdentity(),epoch=_sourceEpoch,check=()=>{if(who!==ratioIdentity()||epoch!==_sourceEpoch||!ratioAuthorized()||EDIT.draft||EDIT.pending||_ledgerBusy||_ratioSnapshotWrite||_ratioRecipientWrite||_ratioSnapshotUnknown)throw Error();};
  try{
    if(!await verifyRatioCapabilityNow())throw Error();check();
    const gist=ratioSnapshotGist(await ghApi('/gists/'+cfg(K.gid)));check();
    const raw=ratioSnapshotFile(gist,RATIO_SNAPSHOT_FILE),registered=ratioSnapshotFile(gist,RATIO_RECIPIENT_FILE);if(raw===null||registered===null)throw Error();
    const manager=await ratioCore.deriveSnapshotManager(cfg(K.gid),cfg(K.key),cfg(K.tok));check();
    if(ratioCore.canonical(ratioSnapshotParse(registered))!==ratioCore.canonical(manager.recipient))throw Error();
    const value=cfg('feeConsole.ratioSnapshotWatermark.'+manager.recipient.recipientId),watermark=value?JSON.parse(value):null;
