  }catch{document.getElementById('ratioSnapshotStatus').textContent='当前快照或管理人核验未通过，没有下载或投递。';return false;}
}
async function checkRatioSnapshotOutcome(event){
  const pending=_ratioSnapshotUnknown;if(event?.isTrusted!==true||!pending||!ratioAuthorized()||pending.who!==ratioIdentity())return false;
